using System;using System.IO;using System.Text;using System.Collections.Generic;using System.Diagnostics;using System.Text.RegularExpressions;using System.Reflection;using System.Security.Cryptography;
internal static class InstallEngine
{
 static string source,root,data,prefix,transaction;
 static string Join(string a,string b){return Path.Combine(a,b);}
 static string Q(string s){if(s.IndexOf('"')>=0)throw new ArgumentException("Invalid path");return "\""+s+"\"";}
 static string Safe(string folder,string relative){relative=relative.Replace('/','\\');if(relative.Length==0||Path.IsPathRooted(relative)||relative.IndexOfAny(new char[]{':','*','?','"','<','>','|'})>=0||Regex.IsMatch(relative,@"(^|\\)\.\.?(\\|$)"))throw new IOException("Invalid install manifest path");string target=Path.GetFullPath(Join(folder,relative));if(!target.StartsWith(Path.GetFullPath(folder).TrimEnd('\\')+"\\",StringComparison.OrdinalIgnoreCase))throw new IOException("Path escapes package");return target;}
 static string[] Manifest(string folder){string[] files=File.ReadAllLines(Join(folder,"install-files.txt"));if(files.Length<10||files.Length>5000)throw new IOException("Invalid install manifest");foreach(string f in files)Safe(folder,f);return files;}
 static void Integrity(string folder,string[] files){Dictionary<string,bool> verified=new Dictionary<string,bool>(StringComparer.OrdinalIgnoreCase);using(SHA256 sha=SHA256.Create())foreach(string line in File.ReadAllLines(Join(folder,"runtime-SHA256SUMS.txt"))){if(!Regex.IsMatch(line,@"^[a-f0-9]{64}  .+$"))throw new IOException("Invalid package checksum entry");string name=line.Substring(66);if(verified.ContainsKey(name))throw new IOException("Duplicate checksum entry");using(FileStream stream=File.OpenRead(Safe(folder,name))){string actual=BitConverter.ToString(sha.ComputeHash(stream)).Replace("-","").ToLowerInvariant();if(actual!=line.Substring(0,64))throw new IOException("Package checksum mismatch: "+name);}verified[name]=true;}foreach(string name in files)if(name!="runtime-SHA256SUMS.txt"&&!verified.ContainsKey(name))throw new IOException("Unverified package file: "+name);}
 static void Copy(string from,string to){Directory.CreateDirectory(Path.GetDirectoryName(to));File.Copy(from,to,true);}
 static int Run(string exe,string args){using(Process p=new Process()){p.StartInfo=new ProcessStartInfo(exe,args);p.StartInfo.UseShellExecute=false;p.StartInfo.CreateNoWindow=true;p.StartInfo.RedirectStandardOutput=true;p.StartInfo.RedirectStandardError=true;p.OutputDataReceived+=delegate{};p.ErrorDataReceived+=delegate{};p.Start();p.BeginOutputReadLine();p.BeginErrorReadLine();if(!p.WaitForExit(30000)){p.Kill();throw new IOException("Runtime check timed out");}p.WaitForExit();return p.ExitCode;}}
 static void Runtime(string folder){if(Run(Join(folder,"YTWin7SabrHost.exe"),"--version")!=0||Run(Join(folder,"PeakMP3\\PeakMP3.exe"),"--version")!=0||Run(Join(folder,"ffmpeg.exe"),"-version")!=0)throw new IOException("The .NET or FFmpeg runtime could not start");}
 static void Registry(string mode,string folder){if(IntegrationRegistration.Run(new string[]{"--integration",mode,root,Join(folder,"registration.txt"),prefix})!=0)throw new IOException("Native registration "+mode+" failed");}
 static void Snapshot(string folder,string[] incoming){Directory.CreateDirectory(folder);Dictionary<string,bool> union=new Dictionary<string,bool>(StringComparer.OrdinalIgnoreCase);foreach(string name in incoming)union[name]=true;if(File.Exists(Join(root,"install-files.txt")))foreach(string name in Manifest(root))union[name]=true;foreach(string name in new string[]{"YTWin7SabrHost.exe","YTWin7SabrHost.exe.config","ffmpeg.exe","ffprobe.exe","register_sabr_host.js","com.ytwin7.sabr.json"})union[name]=true;List<string> before=new List<string>();foreach(string name in union.Keys)if(File.Exists(Safe(root,name))){Copy(Safe(root,name),Safe(Join(folder,"files"),name));before.Add(name);}File.WriteAllLines(Join(folder,"files-before.txt"),before.ToArray());string[] candidates=new string[union.Count];union.Keys.CopyTo(candidates,0);File.WriteAllLines(Join(folder,"files-candidate.txt"),candidates);Registry("snapshot",folder);}
 static void Restore(string folder){Registry("restore",folder);Dictionary<string,bool> before=new Dictionary<string,bool>(StringComparer.OrdinalIgnoreCase);foreach(string name in File.ReadAllLines(Join(folder,"files-before.txt"))){before[name]=true;if(!String.Equals(Safe(root,name),Assembly.GetExecutingAssembly().Location,StringComparison.OrdinalIgnoreCase))Copy(Safe(Join(folder,"files"),name),Safe(root,name));}foreach(string name in File.ReadAllLines(Join(folder,"files-candidate.txt")))if(!before.ContainsKey(name)&&!String.Equals(Safe(root,name),Assembly.GetExecutingAssembly().Location,StringComparison.OrdinalIgnoreCase)&&File.Exists(Safe(root,name)))File.Delete(Safe(root,name));}
 static void Registration(){string manifest=new MiniJson().Serialize(new {name="com.ytwin7.sabr",description="YouTube Downloader local media",path=Join(root,"YTWin7SabrHost.exe"),type="stdio"});manifest=manifest.Substring(0,manifest.Length-1)+",\"allowed_origins\":[\"chrome-extension://eejgbkimfjihhfjmemjgmdjdpmipiohm/\"]}";File.WriteAllText(Join(root,"com.ytwin7.sabr.json"),manifest,new UTF8Encoding(false));Registry("register",data);Registry("verify",data);}
 [STAThread]static int Main(string[] args){
  try{
   source=Path.GetDirectoryName(Assembly.GetExecutingAssembly().Location);prefix=Environment.GetEnvironmentVariable("YTD_INSTALL_TEST_REGISTRY")??"";
   if(prefix.Length>0&&!Regex.IsMatch(prefix,@"^Software\\popovantondev\\YouTubeDownloader\\Tests\\[A-Za-z0-9_-]+\\$"))throw new ArgumentException("Invalid isolated registry namespace");
   string local=prefix.Length>0?Environment.GetEnvironmentVariable("LOCALAPPDATA"):Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData);if(String.IsNullOrEmpty(local))throw new IOException("Local application data is unavailable");
   root=Join(local,"YTWin7_360_MP3");data=Join(local,"YTWin7_WatchCapture");string mode=args.Length>0?args[0]:"install";
   if(mode=="install"){
    string[] files=Manifest(source);foreach(string name in files)if(!File.Exists(Safe(source,name)))throw new FileNotFoundException("Missing package file",name);Integrity(source,files);Runtime(source);Directory.CreateDirectory(root);Directory.CreateDirectory(data);
    transaction=Join(data,"INSTALL_260_"+Guid.NewGuid().ToString("N"));Snapshot(transaction,files);
    string backup=Join(data,"BACKUP_PRE_260");if(File.Exists(Join(root,"YTWin7SabrHost.exe"))&&!Directory.Exists(backup)){Directory.CreateDirectory(backup);foreach(string f in Directory.GetFiles(transaction,"*",SearchOption.AllDirectories))Copy(f,Join(backup,f.Substring(transaction.Length+1)));}
    foreach(string name in files)Copy(Safe(source,name),Safe(root,name));
    if(prefix.Length>0&&Environment.GetEnvironmentVariable("YTD_INSTALL_TEST_FAIL")=="after-copy")throw new IOException("Forced isolated post-copy failure");
    Registration();Runtime(root);Directory.Delete(transaction,true);transaction=null;Console.WriteLine("INSTALL_OK_260");
   }else if(mode=="restore"){Restore(Join(data,"BACKUP_PRE_260"));Console.WriteLine("RESTORE_OK");}
   else if(mode=="uninstall"||mode=="uninstall-app"){
    string[] owned=mode=="uninstall-app"?Manifest(root):new string[0];Registry("remove",data);string manifest=Join(root,"com.ytwin7.sabr.json");if(mode=="uninstall-app"&&File.Exists(manifest))File.Delete(manifest);
    string self=Assembly.GetExecutingAssembly().Location;foreach(string name in owned){string path=Safe(root,name);if(!String.Equals(path,self,StringComparison.OrdinalIgnoreCase)&&File.Exists(path))File.Delete(path);}Console.WriteLine("UNINSTALL_OK");
   }else throw new ArgumentException("Unknown setup operation");return 0;
  }catch(Exception e){Console.Error.WriteLine(e.Message);if(transaction!=null)try{Restore(transaction);Console.Error.WriteLine("Previous version restored");}catch(Exception recovery){Console.Error.WriteLine("Recovery snapshot retained: "+transaction+"; "+recovery.Message);}return 1;}
 }
}
